static void sme_gemm(int n,const float *a,const float *b,float *c) {
    if (n <= 0) return;
    const int vl=(int)svcntsw();
    /* Gather indices count floats. Guard index and tile-counter overflow. */
    if ((size_t)n * (size_t)(vl - 1) > 4294967295ULL ||
        n > 2147483647 - 2 * vl) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                float sum = 0.0f;
                for (int k = 0; k < n; ++k)
                    sum += a[(size_t)i*n+k] * b[(size_t)k*n+j];
                c[(size_t)i*n+j] = sum;
            }
        }
        return;
    }
    const svuint32_t row_indices = svindex_u32(0, n);

svfloat32_t a0=svld1_gather_u32index_f32(
    pi0, a+(size_t)i*n+k, row_indices);
svfloat32_t a1=svld1_gather_u32index_f32(
    pi1, a+(size_t)(i+vl<n?i+vl:i)*n+k, row_indices);

