static void fallback_gemm(int n,const float *restrict A,const float *restrict B,float *restrict C) {
    if(n<=0)return;
    float *at=malloc((size_t)n*n*sizeof(float));
    if(!at) {
        for(int i=0;i<n;i++)for(int j=0;j<n;j++) {
            float x=0;for(int k=0;k<n;k++)x+=A[(size_t)i*n+k]*B[(size_t)k*n+j];
            C[(size_t)i*n+j]=x;
        }
        return;
    }
    sme_transpose(n, A, at);
    sme_gemm(n,at,B,C);
    free(at);
}

